const r=$input.first().json;
const html=String(r.body??r.data??'');
if(Number(r.statusCode)!==200) throw new Error('TELEGRAM_HTTP_'+r.statusCode);
const parts=html.split('data-post="newrulesgeo/').slice(1);
const posts=[];
const decode=s=>s
  .replace(/<br\s*\/?\s*>/gi,'\n')
  .replace(/<a[^>]*>([\s\S]*?)<\/a>/gi,'$1')
  .replace(/<[^>]+>/g,'')
  .replace(/&nbsp;/g,' ')
  .replace(/&amp;/g,'&')
  .replace(/&quot;/g,'"')
  .replace(/&#39;|&apos;/g,"'")
  .replace(/&#036;/g,'$')
  .replace(/&lt;/g,'<')
  .replace(/&gt;/g,'>')
  .trim();
for(const part of parts){
  const id=(part.match(/^(\d+)/)||[])[1];
  const m=part.match(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/i);
  const dt=(part.match(/<time datetime="([^"]+)"/i)||[])[1]||'';
  if(id&&m){
    const text=decode(m[1]);
    if(text) posts.push({
      source_id:'new_rules',
      telegram_post_id:id,
      message_key:'telegram:newrulesgeo:'+id,
      record_id:'relay:new_rules:'+id,
      text,
      published_at:dt,
      source_url:'https://t.me/newrulesgeo/'+id
    });
  }
}
if(!posts.length) throw new Error('NO_STABLE_POSTS_PARSED');
posts.sort((a,b)=>Number(a.telegram_post_id)-Number(b.telegram_post_id));
return [{json:{posts:posts.slice(-20),fetched_at:new Date().toISOString()}}];

const crypto=require('crypto');
const r=$input.first().json,b=r.body??r;
if(Number(r.statusCode)!==200||!Array.isArray(b.values)) throw Error('MACRO_LOG_READ_FAILED');
const h=['record_id','record_type','message_key','gmail_message_id','source_id','received_at','content_hash','origin_ref','operation_id','stage','status','analysis_checkpoint_json','progress_json','notification_json','attempt_count','next_retry_at','error_category','error_code','error_summary','review_json','execution_id','created_at','updated_at','completed_at','schema_version','dataset_id'];
if(JSON.stringify(b.values[0]||[])!==JSON.stringify(h)) throw Error('MACRO_LOG_SCHEMA_MISMATCH');
const rows=b.values.slice(1).filter(x=>x.some(v=>v!==''&&v!=null)).map(x=>Object.fromEntries(h.map((k,i)=>[k,x[i]??''])));
const posts=$('Parse real Telegram posts').first().json.posts;
const done=rows.filter(x=>x.record_type==='PUBLIC_NEWS_RELAY'&&x.source_id==='new_rules'&&x.status==='COMPLETE');
const doneKeys=new Set(done.map(x=>x.record_id));
const doneIds=done.map(x=>Number(String(x.record_id).split(':').pop())).filter(Number.isFinite);
const maxDone=doneIds.length?Math.max(...doneIds):null,firstDone=doneIds.length?Math.min(...doneIds):null;
let candidates=maxDone===null?[posts[posts.length-1]]:posts.filter(p=>Number(p.telegram_post_id)>firstDone&&!doneKeys.has(p.record_id));
candidates=candidates.slice(0,5);
if(!candidates.length) return [{json:{route:'NO_OP',status:'NO_NEW_POSTS',highest_completed:maxDone,checked_posts:posts.length}}];
return candidates.map(p=>({json:{route:'SEND',...p,content_sha256:crypto.createHash('sha256').update(p.text).digest('hex')}}));

const p=$json;if(p.route!=='SEND'||p.source_id!=='new_rules'||!/^\d+$/.test(p.telegram_post_id)||!p.text)throw Error('MACRO_RELAY_INPUT_INVALID');
const nonce=require('crypto').createHash('sha256').update(p.message_key).digest('hex').slice(0,24);
if(p.text.length<=2000)return {json:{...p,delivery_kind:'text',discord_body:{content:p.text,allowed_mentions:{parse:[]},nonce,enforce_nonce:true}}};
const fileName='new-rules-'+p.telegram_post_id+'.txt',data=Buffer.from(p.text,'utf8');if(data.length>5000000)throw Error('MACRO_ATTACHMENT_TOO_LARGE');
return {json:{...p,delivery_kind:'attachment',file_name:fileName,file_bytes:data.length,discord_body:{content:'Full New Rules post attached.\n'+p.source_url,allowed_mentions:{parse:[]},nonce,enforce_nonce:true,attachments:[{id:0,filename:fileName,description:'Original visible Telegram post text'}]}},binary:{attachment:{data:data.toString('base64'),mimeType:'text/plain',fileName}}};

const r=$json,b=r.body??r,p=$('Build exact Discord message').item.json;
const ok=Number(r.statusCode)===200&&typeof b.id==='string'&&b.channel_id==='1562615231761621064'&&b.content===p.discord_body.content&&(p.delivery_kind==='text'||(b.attachments?.length===1&&b.attachments[0].filename===p.file_name&&Number(b.attachments[0].size)===p.file_bytes));
if(!ok) throw Error('MACRO_DISCORD_DELIVERY_FAILED:'+String(r.statusCode||'UNKNOWN')+':'+String(b.message||''));
const now=new Date().toISOString();
const checkpoint=JSON.stringify({telegram_post_id:p.telegram_post_id,text:p.text,published_at:p.published_at,source_url:p.source_url});
const notification=JSON.stringify({channel_id:b.channel_id,message_id:b.id,content_sha256:p.content_sha256,delivery_kind:p.delivery_kind,attachment_id:b.attachments?.[0]?.id||null});
const row=[p.record_id,'PUBLIC_NEWS_RELAY',p.message_key,'',p.source_id,p.published_at||now,p.content_sha256,p.source_url,'relay:'+p.telegram_post_id,'DISCORD_RELAY','COMPLETE',checkpoint,JSON.stringify({source_fetch:'COMPLETE',discord_send:'COMPLETE'}),notification,1,'','','','',JSON.stringify({manual_review_required:false}),$execution.id,now,now,now,'2.0','real'];
return {json:{record_id:p.record_id,telegram_post_id:p.telegram_post_id,text:p.text,channel_id:b.channel_id,message_id:b.id,append_body:{values:[row]}}};

const r=$json,b=r.body??r,p=$('Prepare durable relay receipt').item.json;
if(Number(r.statusCode)!==200||Number(b.updates?.updatedRows)!==1) throw Error('MACRO_RECEIPT_APPEND_FAILED');
return {json:{status:'NEW_RULES_RELAYED',record_id:p.record_id,telegram_post_id:p.telegram_post_id,channel_id:p.channel_id,message_id:p.message_id,durable_receipt:true,text_preserved:true,source_id:"new_rules"}};
